export const LEGACY_FRAMES=[-1400,-400,-100,117,650,700,850,1000,1200,1300,1600,1750,1850,1932];
export const FRAMES=[-1750,-1400,-500,-400,-323,-300,-200,-100,117,200,300,400,500,600,650,700,850,900,1000,1100,1200,1279,1300,1400,1492,1500,1530,1600,1650,1700,1750,1800,1850,1880,1914,1932];
export const dateLabel=y=>y<0?`${Math.abs(y)} ق.م`:`${y} م`;
export const ordinal=y=>y<0?y+1:y;
export function duration(a,b){if(!a||!b)throw new Error('No year zero');return ordinal(b)-ordinal(a)}
export function normalize(q){return String(q).normalize('NFKD').replace(/[\u064B-\u065F\u0670]/g,'').replace(/ـ/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[٠-٩]/g,x=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(x))).toLowerCase().trim()}
export function search(items,q,type='all'){const terms=normalize(q).split(/\s+/).filter(Boolean);return items.filter(x=>(type==='all'||x.type===type)&&terms.every(t=>normalize([x.title,x.summary,x.periodLabel,...(x.tags||[]),...(x.sections||[]).map(s=>s.text)].join(' ')).includes(t)))}
export function activeAt(items,year){return items.filter(x=>x.start<=year&&x.end>=year)}
export function nearestFrame(year){return FRAMES.reduce((best,y)=>Math.abs(ordinal(y)-ordinal(year))<Math.abs(ordinal(best)-ordinal(year))?y:best)}
const MAX_STEPS=20; // أطول رحلة؛ وصفحة الرحلة نفسها تقصّ التقدم على عدد محطاتها
export function readStore(storage){const empty={saved:[],journeys:{},city:[]};try{let x=JSON.parse(storage.getItem('atlas-v1')||'{}');if(!x||typeof x!=='object'||Array.isArray(x))return empty;const journeys={};for(const[id,p]of Object.entries(x.journeys||{})){if(p&&typeof p==='object'&&!Array.isArray(p))journeys[id]={step:validStep(p.step,MAX_STEPS),done:[...new Set(Array.isArray(p.done)?p.done.filter(v=>Number.isInteger(v)&&v>=0&&v<MAX_STEPS):[])]}}return{saved:[...new Set(Array.isArray(x.saved)?x.saved.filter(i=>typeof i==='string'):[])],journeys,city:[...new Set(Array.isArray(x.city)?x.city.filter(i=>Number.isInteger(i)&&i>=0&&i<4):[])]}}catch{return empty}}
export function saveStore(storage,state){try{storage.setItem('atlas-v1',JSON.stringify(state));return true}catch{return false}}
export function answerIsCorrect(quiz,index){return Number.isInteger(index)&&index===quiz.answer}
export function validStep(value,count){return Number.isInteger(value)?Math.max(0,Math.min(count-1,value)):0}
export function validateContent(items,sources){const ids=new Set();for(const x of items){if(ids.has(x.id))throw new Error('Duplicate id '+x.id);ids.add(x.id);if(!x.title||!x.summary)throw new Error('Missing content '+x.id);if(!x.start||!x.end||x.start>x.end)throw new Error('Invalid dates '+x.id);if(!x.sources?.length||x.sources.some(s=>!sources[s]))throw new Error('Missing source '+x.id);if(x.point&&(!Array.isArray(x.point)||x.point.length!==2||Math.abs(x.point[0])>180||Math.abs(x.point[1])>90))throw new Error('Invalid coordinates '+x.id);if(x.quiz&&(!x.quiz.options?.[x.quiz.answer]||!x.quiz.explanation))throw new Error('Invalid quiz '+x.id)}for(const x of items)for(const id of x.related||[])if(!ids.has(id))throw new Error('Missing related '+id);return true}
